(function(){(()=>{"use strict";const e=(a,n,r,o,i,s,t)=>({g:a,p:n,n:r,f:o,how:i,ex:s,...t?{fig:t}:{}});window.PhysicaRankEmiJee={chapter:"Electromagnetic Induction and Alternating Current",secs:["Magnetic flux and Faraday\u2019s law","Lenz\u2019s law and induced charge","Motional EMF","Self and mutual inductance","Energy, RL circuits, eddy currents and generators","AC values: peak, rms and average","AC through R, L and C; phasors","Series LCR circuit and resonance","Power, LC oscillations and the transformer"],table:[["Magnetic flux \u03A6 = BA cos\u03B8","ML\xB2T\u207B\xB2A\u207B\xB9 (weber)"],["Induced EMF \u03B5 = d\u03A6/dt","ML\xB2T\u207B\xB3A\u207B\xB9 (volt)"],["Magnetic field B (tesla)","MT\u207B\xB2A\u207B\xB9"],["Inductance L or M (henry)","ML\xB2T\u207B\xB2A\u207B\xB2"],["Time constant \u03C4 = L/R","T (second)"],["Reactance XL = \u03C9L, XC = 1/\u03C9C","ML\xB2T\u207B\xB3A\u207B\xB2 (ohm)"],["Impedance Z","ML\xB2T\u207B\xB3A\u207B\xB2 (ohm)"],["Energy in an inductor \xBDLI\xB2","ML\xB2T\u207B\xB2 (joule)"],["Energy density of a field B\xB2/2\u03BC\u2080","ML\u207B\xB9T\u207B\xB2 (J/m\xB3)"],["Angular frequency \u03C9 = 2\u03C0f","T\u207B\xB9 (rad/s)"],["Quality factor Q, power factor cos\u03C6","dimensionless"],["Rate of change of flux d\u03A6/dt","ML\xB2T\u207B\xB3A\u207B\xB9 (V)"]],formulas:[e("Magnetic flux and Faraday\u2019s law",1,"Magnetic flux","\u03A6 = \u222BB\xB7dA = BA cos\u03B8 for a uniform field \xB7 \u03B8 is the angle between B and the normal to the loop (not the plane) \xB7 unit: weber, 1 Wb = 1 T m\xB2 \xB7 maximum when the plane is perpendicular to B, zero when the plane is parallel to B \xB7 for N turns the flux linked is N\u03A6","Draw the normal to the loop first and then find the angle between it and B. Many mistakes come from taking the angle with the plane.","B = 0.5 T, loop 10 cm \xD7 20 cm, B at 60\xB0 to the normal: \u03A6 = 0.5 \xD7 0.02 \xD7 cos 60\xB0 = 5 \xD7 10\u207B\xB3 Wb.","eifar"),e("Magnetic flux and Faraday\u2019s law",1,"Faraday\u2019s law","\u03B5 = \u2212N{d\u03A6;dt} \xB7 average EMF = \u2212N{\u0394\u03A6;\u0394t} \xB7 an EMF is induced whenever the flux changes: B changes, A changes or \u03B8 changes \xB7 EMF depends on the rate of change, not on the flux itself \xB7 induced current I = {\u03B5;R}","Write \u03A6 in terms of t, then differentiate. For an average value use the final minus the initial flux over the time taken.","A coil of 100 turns: the flux through each turn falls from 0.02 Wb to 0.005 Wb in 0.1 s. \u03B5 = 100 \xD7 0.015 \xF7 0.1 = 15 V.","eifar"),e("Magnetic flux and Faraday\u2019s law",1,"Three ways to change the flux","B changing: \u03B5 = \u2212NA cos\u03B8 {dB;dt} \xB7 area changing: \u03B5 = \u2212NB cos\u03B8 {dA;dt} \xB7 angle changing: \u03B5 = NBA sin\u03B8 {d\u03B8;dt} \xB7 a loop that is moved inside a uniform field without changing A or \u03B8 has no EMF \xB7 a loop fully inside a uniform field, moving or not, has no EMF","Ask which of B, A and \u03B8 varies and keep the other two as constants.","B = 0.2 T falls to zero in 0.5 s through a loop of area 0.01 m\xB2 (\u03B8 = 0): \u03B5 = 0.01 \xD7 0.2 \xF7 0.5 = 4 mV."),e("Magnetic flux and Faraday\u2019s law",2,"Induced electric field","a changing B makes a non-conservative E field: \u222EE\xB7dl = \u2212{d\u03A6;dt} \xB7 circular region of radius R with {dB;dt} uniform: inside, E = {r;2}{dB;dt} \xB7 outside, E = {R\xB2;2r}{dB;dt} \xB7 the field lines are closed circles \xB7 an induced field is not due to charges, so it has no potential","Take a circle of radius r through the point, equate E \xD7 2\u03C0r to the rate of change of flux through it and solve. Remember that only the field region contributes outside.","R = 10 cm, dB/dt = 0.02 T/s: at r = 5 cm inside, E = 0.05 \xF7 2 \xD7 0.02 = 5 \xD7 10\u207B\u2074 V/m. At r = 20 cm: E = 0.01 \xF7 0.4 \xD7 0.02 = 5 \xD7 10\u207B\u2074 V/m."),e("Lenz\u2019s law and induced charge",1,"Lenz\u2019s law","the induced current flows so as to oppose the change of flux that produces it \xB7 flux growing: the induced field is opposite to B \xB7 flux falling: the induced field is in the same direction as B \xB7 it follows from conservation of energy \xB7 the minus sign in Faraday\u2019s law carries it","First decide whether the flux through the loop is increasing or decreasing; then the induced field is opposite (or the same); then use the right-hand rule for the direction of the current.","B pointing into the page grows through a loop. The induced field must point out of the page, so the current is anticlockwise.","eifar"),e("Lenz\u2019s law and induced charge",1,"Magnet moving towards a coil","the near face of the coil becomes the same pole as the approaching pole (repulsion) \xB7 the near face becomes the opposite pole when the magnet moves away (attraction) \xB7 the magnet always feels a force against its motion \xB7 the work done by hand turns into heat in the coil","Name the pole that faces the magnet by saying that the coil resists: it pushes the incoming pole away and holds on to the departing one.","A north pole is pushed towards a coil: the face near it becomes a north pole, so the current is anticlockwise when seen from the magnet."),e("Lenz\u2019s law and induced charge",1,"Induced charge","q = \u222BI dt = {N\u0394\u03A6;R} \xB7 independent of the time taken \xB7 the current is large for fast change and small for slow change but the charge is the same \xB7 flipping a coil through 180\xB0 gives \u0394\u03A6 = 2BA \xB7 q = (change of flux linked) \xF7 (total resistance)","Do not integrate the current: use q = N\u0394\u03A6/R straight away. Take R as the resistance of the whole circuit.","A coil of 50 turns and area 0.01 m\xB2, with R = 5 \u03A9, is turned through 180\xB0 in B = 0.2 T (face perpendicular to B at the start). \u0394\u03A6 = 2 \xD7 0.2 \xD7 0.01 = 4 \xD7 10\u207B\xB3 Wb and q = 50 \xD7 4 \xD7 10\u207B\xB3 \xF7 5 = 0.04 C."),e("Lenz\u2019s law and induced charge",2,"Heat produced and the time dependence","heat H = \u222B{\u03B5\xB2;R}dt \xB7 if \u03B5 is constant, H = {\u03B5\xB2;R}t \xB7 I = {1;R}{d\u03A6;dt}, so q = {1;R}\u0394\u03A6 and charge is the area under the I\u2013t graph \xB7 for a flux that changes uniformly the current is constant","If \u03A6 is given as a function of time, differentiate for \u03B5, divide by R for I and integrate I\xB2 R for the heat.","\u03A6 = 3t\xB2 Wb in a loop of 2 \u03A9: \u03B5 = 6t volt, I = 3t ampere. The charge in the first 2 s is \u222B3t dt = 6 C."),e("Motional EMF",1,"Straight rod in a magnetic field","\u03B5 = \u222B(v \xD7 B)\xB7dl = Blv for v \u22A5 B \u22A5 l \xB7 general: \u03B5 = B l v sin\u03B8 with l, v, B at the angles that matter \xB7 if the rod is slanted, use the effective length l\u2032 perpendicular to v \xB7 no EMF when v is parallel to B or when the rod is parallel to v \xB7 the end where positive charge gathers is found from the direction of v \xD7 B","Use only the components that are at right angles to each other. For a rod that is not straight, use the straight line between its ends.","A rod of length 0.5 m moves at 10 m/s at right angles to B = 0.2 T and to its length: \u03B5 = 0.2 \xD7 0.5 \xD7 10 = 1 V.","eirail"),e("Motional EMF",1,"Rod on rails: current, force and power","I = {Blv;R} \xB7 magnetic force F = BIl = {B\xB2l\xB2v;R} opposes the motion \xB7 power to push at constant speed P = Fv = {B\xB2l\xB2v\xB2;R} = I\xB2R = \u03B5 I \xB7 this equals the heat produced in R \xB7 by Lenz\u2019s law the force always opposes the velocity","Find \u03B5 first, then I, then F. The mechanical power supplied equals the electrical power lost as heat, which is a check of every answer.","B = 0.2 T, l = 0.5 m, v = 10 m/s, R = 2 \u03A9: I = 1 \xF7 2 = 0.5 A, F = 0.2 \xD7 0.5 \xD7 0.5 = 0.05 N and P = 0.05 \xD7 10 = 0.5 W = I\xB2R.","eirail"),e("Motional EMF",1,"Rod released on rails (terminal speed)","a rod of mass m on rails with an external force F: m{dv;dt} = F \u2212 {B\xB2l\xB2v;R} \xB7 terminal speed vT = {FR;B\xB2l\xB2} \xB7 for a rod slipping down a smooth incline of angle \u03B1: vT = {mgR sin\u03B1;B\xB2l\xB2cos\xB2\u03B1} (field vertical) \xB7 v = vT(1 \u2212 e^(\u2212t/\u03C4)) with \u03C4 = {mR;B\xB2l\xB2}","At the terminal speed the force of the field equals the driving force; set them equal to find vT directly without solving the differential equation.","m = 0.1 kg, l = 1 m, R = 1 \u03A9, B = 1 T, rod falling vertically on vertical rails (g = 10): vT = 0.1 \xD7 10 \xD7 1 \xF7 1 = 1 m/s."),e("Motional EMF",1,"Rotating rod and disc","\u03B5 = {1;2}B\u03C9l\xB2 = {1;2}Bl\xB2(2\u03C0f) = BAf \xB7 the speed of the free end is \u03C9l and the mean speed is \u03C9l/2 \xB7 the same holds for a disc or a spoke of radius l \xB7 centre at O, potential difference between the axle and the rim of a disc is {1;2}B\u03C9r\xB2 \xB7 between two points at r\u2081 and r\u2082: \u03B5 = {1;2}B\u03C9(r\u2082\xB2 \u2212 r\u2081\xB2) \xB7 if the rod rotates about a point not at its end, the two parts give opposite EMFs","Use the average speed \u03C9l/2 of the rod in \u03B5 = Bl(v average). For two parts of a rod about a pivot, subtract the two values.","B = 0.1 T, l = 0.5 m, \u03C9 = 20 rad/s: \u03B5 = 0.5 \xD7 0.1 \xD7 20 \xD7 0.25 = 0.25 V."),e("Motional EMF",1,"Rectangular loop entering a field","while entering: \u03B5 = Bav (a the width cut by the field edge) and F = {B\xB2a\xB2v;R} \xB7 fully inside a uniform field: \u03B5 = 0, no force \xB7 while leaving: \u03B5 = Bav in the opposite sense \xB7 duration of each stage = {b;v} (b the length of the loop along the motion) \xB7 I\u2013t and F\u2013t graphs are rectangular pulses, with opposite signs for entering and leaving","Divide the motion into entering, inside and leaving, and write the flux change for each part.","A square loop of side 0.1 m and R = 0.5 \u03A9 enters a field of 0.5 T at 2 m/s: \u03B5 = 0.5 \xD7 0.1 \xD7 2 = 0.1 V, I = 0.2 A, F = 0.5 \xD7 0.2 \xD7 0.1 = 0.01 N, for t = 0.05 s."),e("Motional EMF",2,"Wire loop or coil rotating in a field","\u03A6 = NBA cos \u03C9t \xB7 \u03B5 = NBA\u03C9 sin \u03C9t \xB7 peak value \u03B5\u2080 = NBA\u03C9 \xB7 \u03B5 is zero when the plane is perpendicular to B, and maximum when the plane is parallel to B \xB7 frequency f = {\u03C9;2\u03C0} \xB7 the same coil in the same field with half the speed gives half the peak EMF","Write the angle at t = 0 first. If the plane is perpendicular to B at t = 0, \u03B5 goes as sin \u03C9t.","N = 100, B = 0.05 T, A = 0.02 m\xB2, \u03C9 = 100 rad/s: \u03B5\u2080 = 100 \xD7 0.05 \xD7 0.02 \xD7 100 = 10 V."),e("Self and mutual inductance",1,"Self-inductance","\u03A6 (linked) = LI \xB7 \u03B5 = \u2212L{dI;dt} \xB7 L depends on the shape, the number of turns and the core, not on I \xB7 unit: henry, 1 H = 1 V s/A \xB7 the induced EMF opposes the change of current, never the current itself \xB7 L is the inertia of the circuit against change of current","Write the flux linked as N\u03A6 = LI to find L. In circuits use \u03B5 = L dI/dt as a drop across the inductor.","L = 0.5 H and the current changes at 4 A/s: \u03B5 = 0.5 \xD7 4 = 2 V."),e("Self and mutual inductance",1,"Inductance of a solenoid","L = \u03BC\u2080n\xB2Al = {\u03BC\u2080N\xB2A;l} (n turns per metre, N turns, area A, length l) \xB7 with a core of relative permeability \u03BCr, multiply by \u03BCr \xB7 L \u221D N\xB2 \xB7 for a toroid L = {\u03BC\u2080N\xB2A;2\u03C0R} \xB7 doubling the turns on the same length gives 4L","Check the dependence first: L \u221D N\xB2 A / l for the same core. For a changed length at the same number of turns L \u221D 1/l.","N = 1000, l = 0.5 m, A = 2 \xD7 10\u207B\u2074 m\xB2: L = 4\u03C0 \xD7 10\u207B\u2077 \xD7 10\u2076 \xD7 2 \xD7 10\u207B\u2074 \xF7 0.5 = 5.0 \xD7 10\u207B\u2074 H = 0.5 mH."),e("Self and mutual inductance",1,"Mutual inductance","\u03A6\u2082 = MI\u2081 \xB7 \u03B5\u2082 = \u2212M{dI\u2081;dt} \xB7 M = {\u03BC\u2080N\u2081N\u2082A;l} for a coil wound over a long solenoid \xB7 M\u2081\u2082 = M\u2082\u2081 \xB7 M = k\u221A(L\u2081L\u2082), 0 \u2264 k \u2264 1 (k = 1 means no flux leaks) \xB7 depends on the geometry, the relative position and the core","Remember that the EMF in the second coil comes from the changing current in the first. M is the same both ways, so you may choose the easier coil to calculate it.","M = 0.2 H and the current in the primary changes at 5 A/s: \u03B5 in the secondary = 0.2 \xD7 5 = 1 V."),e("Self and mutual inductance",1,"Coils in series","L = L\u2081 + L\u2082 + 2M if the fluxes add (same sense of winding) \xB7 L = L\u2081 + L\u2082 \u2212 2M if the fluxes oppose \xB7 far apart coils (M = 0): L = L\u2081 + L\u2082 \xB7 parallel far apart: {1;L} = {1;L\u2081} + {1;L\u2082} \xB7 equal coils joined to cancel the flux (k = 1): L = 0","Decide whether the currents go the same way round both coils; this fixes the sign of 2M.","L\u2081 = 2 H, L\u2082 = 3 H and M = 1 H: aiding, L = 2 + 3 + 2 = 7 H; opposing, L = 2 + 3 \u2212 2 = 3 H."),e("Energy, RL circuits, eddy currents and generators",1,"Energy stored in an inductor","U = {1;2}LI\xB2 \xB7 energy density u = {B\xB2;2\u03BC\u2080} \xB7 for a solenoid U = u \xD7 (volume) = {B\xB2;2\u03BC\u2080}Al \xB7 the energy comes from the battery while the current grows and is returned when it falls \xB7 compare a capacitor, U = {1;2}CV\xB2","Use U = \xBDLI\xB2 for the total energy and u = B\xB2/2\u03BC\u2080 if the field is given. The two agree for a solenoid.","L = 0.5 H and I = 2 A: U = 0.5 \xD7 0.5 \xD7 4 = 1 J."),e("Energy, RL circuits, eddy currents and generators",1,"Growth of current in an RL circuit","I = {E;R}(1 \u2212 e^(\u2212t/\u03C4)) with \u03C4 = {L;R} \xB7 at t = 0, I = 0 and {dI;dt} = {E;L} (the inductor acts like a break) \xB7 at t = \u03C4, I = 0.632 {E;R} \xB7 at t = \u221E the inductor is a plain wire, I = {E;R} \xB7 voltage across L: VL = E e^(\u2212t/\u03C4) \xB7 time to reach half the final value: 0.693\u03C4 \xB7 at the instant of closing, the full battery EMF appears across the inductor","Write the three numbers: I at t = 0, at t = \u221E and the time constant. Then use the exponential only if a value at a given time is asked.","E = 12 V, R = 4 \u03A9, L = 2 H: \u03C4 = 0.5 s, final I = 3 A and at t = 0.5 s, I = 3 \xD7 0.632 = 1.90 A.","eirl"),e("Energy, RL circuits, eddy currents and generators",1,"Decay of current in an RL circuit","I = I\u2080e^(\u2212t/\u03C4) with \u03C4 = {L;R} \xB7 after one time constant I = 0.368I\u2080 \xB7 after t = 0.693\u03C4 the current is half \xB7 the energy {1;2}LI\u2080\xB2 is all turned into heat in the resistor \xB7 the induced EMF can be much larger than E if the circuit is broken suddenly (a spark) because \u03C4 becomes very small","Use the value of the current at the start as I\u2080, not the value of E/R unless the current had reached it.","I\u2080 = 3 A and \u03C4 = 0.5 s: at t = 1 s, I = 3 e\u207B\xB2 = 3 \xD7 0.135 = 0.406 A.","eirl"),e("Energy, RL circuits, eddy currents and generators",1,"Two-resistor RL circuits (switch just closed or long after)","just after closing: the inductor branch carries no current, so treat it as open \xB7 long after: the inductor has no EMF, so treat it as a wire (zero resistance) \xB7 just after opening: the current in the inductor is the same as just before \xB7 for a battery of E with R\u2081 in series with (R\u2082 in parallel with L): at t = 0 I = {E;R\u2081 + R\u2082} and at t = \u221E I = {E;R\u2081}","Replace the inductor by an open circuit at t = 0 and by a wire at t = \u221E, then solve the resistor circuit. The current in L cannot jump.","E = 10 V, R\u2081 = 5 \u03A9 in series with the parallel pair R\u2082 = 5 \u03A9 and L: at t = 0, I = 10 \xF7 10 = 1 A; at t = \u221E, I = 10 \xF7 5 = 2 A."),e("Energy, RL circuits, eddy currents and generators",2,"Eddy currents","closed loops of current induced in a bulk conductor by a changing flux or by its motion in a field \xB7 they oppose the cause (Lenz) and heat the metal \xB7 uses: induction furnace, magnetic braking of trains, damping of galvanometer and balance pointers, energy meters \xB7 reduced by laminating the core (thin insulated sheets), which cuts the loop area \xB7 a plate with slits falls faster through a magnet than a solid plate","Say what they do in one line: they brake the motion and produce heat. For a falling magnet or plate through a tube, the speed reaches a terminal value.","A solid copper plate and a plate with slits swing into a magnet: the solid one stops sooner, since larger loops carry larger eddy currents."),e("Energy, RL circuits, eddy currents and generators",2,"AC generator and back EMF","coil of N turns, area A, rotating at \u03C9 in field B: \u03B5 = NBA\u03C9 sin \u03C9t \xB7 mechanical energy turns into electrical energy \xB7 in a motor the rotating coil produces a back EMF opposing the supply: I = {E \u2212 Eb;R} \xB7 starting current is large because Eb = 0 at rest \xB7 the back EMF is largest at full speed, so the current falls","Treat the motor as a source (E) and a resistor (R) with an opposing source Eb in series.","E = 220 V, R = 4 \u03A9 and Eb = 200 V: I = 20 \xF7 4 = 5 A. At rest the current would be 220 \xF7 4 = 55 A."),e("AC values: peak, rms and average",1,"Alternating current and its values","i = I\u2080 sin \u03C9t, v = V\u2080 sin \u03C9t \xB7 \u03C9 = 2\u03C0f = {2\u03C0;T} \xB7 I rms = {I\u2080;\u221A2} = 0.707I\u2080 \xB7 mean over a half cycle = {2I\u2080;\u03C0} = 0.637I\u2080 \xB7 the mean over a full cycle is zero \xB7 form factor = {rms;mean of half cycle} = 1.11 \xB7 the rms is the value of the steady DC that gives the same heat in a resistor \xB7 ammeters and voltmeters for AC read rms","Use rms for any heating, power or meter reading, the half-cycle average for rectified charge, and the peak for insulation or breakdown.","A mains voltage of 220 V (rms) has the peak 220 \xD7 1.414 = 311 V. A current of peak 10 A has rms 7.07 A and half-cycle mean 6.37 A."),e("AC values: peak, rms and average",1,"Reading a time function","from v = V\u2080 sin(\u03C9t + \u03C6): V\u2080 is the peak, \u03C9 the angular frequency, \u03C6 the phase \xB7 f = {\u03C9;2\u03C0} \xB7 V rms = {V\u2080;\u221A2} \xB7 time to reach the first peak from the zero crossing = {T;4} \xB7 for v = 311 sin 100\u03C0t: f = 50 Hz and the rms is 220 V \xB7 in sin and cos forms, cos \u03C9t = sin(\u03C9t + \u03C0/2)","Compare the given expression with I\u2080 sin(\u03C9t + \u03C6) term by term. Do not multiply the peak by 0.707 twice.","v = 311 sin(100\u03C0t): \u03C9 = 100\u03C0 so f = 50 Hz and T = 20 ms; V rms = 311 \xF7 1.414 = 220 V."),e("AC values: peak, rms and average",1,"Rms of other waveforms","rms = \u221A(mean of i\xB2) \xB7 pure sine: {I\u2080;\u221A2} \xB7 square wave of height \xB1I\u2080: I\u2080 \xB7 half-wave rectified sine: {I\u2080;2} \xB7 DC plus a sine, I = Id + I\u2080 sin \u03C9t: \u221A(Id\xB2 + {I\u2080\xB2;2}) \xB7 triangular or sawtooth wave of peak I\u2080: {I\u2080;\u221A3} \xB7 rms over time of a pulse of I for a fraction \u03C4 of the period: I\u221A\u03C4","Square the current, average over a whole period and take the root. Sine squared averages to 1/2.","I = 3 + 4 sin \u03C9t: Irms = \u221A(9 + 8) = \u221A17 = 4.12 A (the mean is 3 A)."),e("AC through R, L and C; phasors",1,"Phasors and phase","a phasor is a rotating vector of length equal to the peak value; its projection on the vertical axis is the instantaneous value \xB7 all phasors turn anticlockwise at \u03C9 \xB7 the angle between two phasors is their phase difference \xB7 resistor: v and i in phase \xB7 inductor: v leads i by 90\xB0 \xB7 capacitor: i leads v by 90\xB0","Memory aid: for L the current lags (V leads I); for C the current leads. Draw I along the axis for a series circuit, V along the axis for a parallel one.","For a pure inductor with i = I\u2080 sin \u03C9t, v = V\u2080 sin(\u03C9t + 90\xB0) = V\u2080 cos \u03C9t.","eiphas"),e("AC through R, L and C; phasors",1,"Inductive reactance","XL = \u03C9L = 2\u03C0fL \xB7 V\u2080 = I\u2080XL \xB7 XL is zero for DC and grows with frequency \xB7 current lags the voltage by \u03C0/2 \xB7 average power over a cycle is zero \xB7 energy is stored and returned each quarter cycle \xB7 an inductor lets low frequencies through and blocks high ones (choke)","Take XL straight from the frequency: if f doubles, XL doubles. Use rms values on both sides if you want rms current.","L = 0.1 H at 50 Hz: XL = 2\u03C0 \xD7 50 \xD7 0.1 = 31.4 \u03A9. On 220 V the rms current is 220 \xF7 31.4 = 7.0 A."),e("AC through R, L and C; phasors",1,"Capacitive reactance","XC = {1;\u03C9C} = {1;2\u03C0fC} \xB7 V\u2080 = I\u2080XC \xB7 XC is infinite for DC and falls as f rises \xB7 current leads the voltage by \u03C0/2 \xB7 average power over a cycle is zero \xB7 a capacitor passes high frequencies and blocks DC (a blocking capacitor)","The reactance goes the opposite way to that of the inductor: if f doubles, XC halves.","C = 100 \u03BCF at 50 Hz: XC = 1 \xF7 (2\u03C0 \xD7 50 \xD7 10\u207B\u2074) = 31.8 \u03A9."),e("AC through R, L and C; phasors",2,"Variation with frequency","R is independent of f \xB7 XL \u221D f is a straight line through the origin \xB7 XC \u221D {1;f} is a hyperbola \xB7 they cross at f\u2080 = {1;2\u03C0\u221A(LC)}, where XL = XC \xB7 for f < f\u2080 the circuit is capacitive; for f > f\u2080 it is inductive \xB7 a bulb in series with a capacitor gets brighter if f rises; with an inductor, dimmer","Compare \u03C9L and 1/\u03C9C first to decide whether the net reactance is inductive or capacitive.","L = 1 mH and C = 10 \u03BCF: f\u2080 = 1592 Hz. At 50 Hz XL = 0.31 \u03A9 and XC = 318 \u03A9, so the circuit is capacitive."),e("Series LCR circuit and resonance",1,"Impedance of series circuits","LR: Z = \u221A(R\xB2 + XL\xB2), tan\u03C6 = {XL;R}, voltage leads \xB7 CR: Z = \u221A(R\xB2 + XC\xB2), tan\u03C6 = {XC;R}, current leads \xB7 LCR: Z = \u221A(R\xB2 + (XL \u2212 XC)\xB2), tan\u03C6 = {XL \u2212 XC;R} \xB7 I = {V;Z} \xB7 V\xB2 = VR\xB2 + (VL \u2212 VC)\xB2 \xB7 the voltages across L or C can be larger than the supply","Draw the phasor triangle: R along the axis, XL up, XC down. The hypotenuse is Z, and the angle is \u03C6.","R = 30 \u03A9, XL = 70 \u03A9, XC = 30 \u03A9: Z = \u221A(900 + 1600) = 50 \u03A9 and \u03C6 = tan\u207B\xB9(40/30) = 53\xB0. On 100 V rms, I = 2 A.","eiphas"),e("Series LCR circuit and resonance",1,"Resonance","XL = XC at \u03C9\u2080 = {1;\u221A(LC)}, f\u2080 = {1;2\u03C0\u221A(LC)} \xB7 Z = R is the minimum, I = {V;R} is the maximum \xB7 V and I are in phase, cos\u03C6 = 1 \xB7 VL = VC but they are opposite and cancel \xB7 the voltage across L (or C) is Q times the supply \xB7 energy goes back and forth between L and C, while R takes the power","At resonance the circuit behaves as a pure resistor. Use this to find the current, the power and the voltage across each part.","L = 1 mH and C = 10 \u03BCF: \u03C9\u2080 = 1 \xF7 \u221A(10\u207B\u2078) = 10\u2074 rad/s and f\u2080 = 1592 Hz. With R = 2 \u03A9 and E = 10 V rms, I = 5 A.","eirlc"),e("Series LCR circuit and resonance",1,"Quality factor and bandwidth","Q = {\u03C9\u2080L;R} = {1;\u03C9\u2080CR} = {1;R}\u221A({L;C}) \xB7 Q = {\u03C9\u2080;\u0394\u03C9} = {f\u2080;f\u2082 \u2212 f\u2081} where f\u2081 and f\u2082 are the half-power points (I falls to 0.707 of the maximum) \xB7 \u0394\u03C9 = {R;L} \xB7 the voltage across L or C at resonance is QE \xB7 a smaller R gives a larger Q, a sharper and taller peak, and a narrower band \xB7 Q has no unit","Q describes the sharpness. To find the bandwidth, \u0394f = f\u2080/Q, and use it for the half-power points f\u2080 \xB1 \u0394f/2 (for large Q).","L = 1 mH, C = 10 \u03BCF, R = 2 \u03A9: Q = 10 \xF7 2 = 5 and the bandwidth = 1592 \xF7 5 = 318 Hz. At E = 10 V the voltage across the inductor is 50 V.","eirlc"),e("Series LCR circuit and resonance",2,"Same current for two frequencies","a current I below the peak is found at two frequencies f\u2081 and f\u2082, with f\u2081f\u2082 = f\u2080\xB2 \xB7 so f\u2080 = \u221A(f\u2081f\u2082) \xB7 the circuit is capacitive at the lower one and inductive at the upper \xB7 the impedance and the power are the same at both","Use the symmetry in \u03C9\u2081\u03C9\u2082 = 1/LC to find L or C from the two frequencies.","The same current flows at 400 Hz and at 900 Hz: f\u2080 = \u221A(400 \xD7 900) = 600 Hz."),e("Series LCR circuit and resonance",2,"Tuning by changing C or L","f\u2080 \u221D {1;\u221A(LC)} \xB7 to double f\u2080, reduce C to a quarter \xB7 to halve f\u2080, make L four times \xB7 a radio picks one station when its f\u2080 equals the station frequency \xB7 for XL > XC (inductive) raise C to approach resonance; for XC > XL lower C","Use f\u2080 \u221D 1/\u221A(LC) to scale. Check which of XL and XC is larger before deciding which way to move.","A radio tunes from 500 kHz to 1500 kHz by changing C: the ratio of the capacitances = (1500/500)\xB2 = 9."),e("Power, LC oscillations and the transformer",1,"Power and power factor","P(avg) = VrmsIrms cos\u03C6 = Irms\xB2R \xB7 cos\u03C6 = {R;Z} = power factor, between 0 and 1 \xB7 apparent power VrmsIrms (VA) \xB7 pure L or C: \u03C6 = 90\xB0, so P = 0 \xB7 at resonance cos\u03C6 = 1 \xB7 a low power factor means more current for the same power and larger line loss","Find Z first, then cos\u03C6 = R/Z, and then use P = Vrms\xB2 R/Z\xB2 or Irms\xB2 R. Use rms values only.","R = 30 \u03A9, XL = 40 \u03A9, V = 100 V rms: Z = 50 \u03A9, I = 2 A, cos\u03C6 = 0.6, P = 2 \xD7 100 \xD7 0.6 = I\xB2R = 4 \xD7 30 = 120 W."),e("Power, LC oscillations and the transformer",1,"Wattless current","the current has a component Icos\u03C6 in phase with V (does the work) and a component Isin\u03C6 at 90\xB0 (wattless) \xB7 wattless current = Irms sin\u03C6 \xB7 for a pure inductor or capacitor the whole current is wattless \xB7 the average power in the wattless part is zero","Resolve the current along the voltage and at right angles to it. Only the first part carries power.","I = 2 A and cos\u03C6 = 0.6: sin\u03C6 = 0.8, wattless current = 1.6 A and the useful component = 1.2 A."),e("Power, LC oscillations and the transformer",1,"LC oscillations","\u03C9 = {1;\u221A(LC)}, T = 2\u03C0\u221A(LC) \xB7 q = Q\u2080 cos \u03C9t, I = \u2212Q\u2080\u03C9 sin \u03C9t \xB7 total energy \xBDLI\u2080\xB2 = {Q\u2080\xB2;2C} is constant (no resistance) \xB7 UE = {q\xB2;2C}, UB = \xBDLi\xB2 \xB7 charge and current are 90\xB0 out of phase: UE is maximum when i = 0 \xB7 UE = UB when q = {Q\u2080;\u221A2} \xB7 the energies oscillate at a frequency 2f \xB7 with R, the oscillations are damped","Treat it like a spring and mass: q is the position, i the velocity, 1/C the spring constant and L the mass. Conserve the energy.","L = 1 mH, C = 10 \u03BCF, Q\u2080 = 100 \u03BCC: \u03C9 = 10\u2074 rad/s, I\u2080 = Q\u2080\u03C9 = 1 A and the energy = Q\u2080\xB2/2C = 5 \xD7 10\u207B\u2074 J = \xBDLI\u2080\xB2."),e("Power, LC oscillations and the transformer",2,"Time and energy sharing in LC","the capacitor discharges fully in {T;4} \xB7 equal energy in L and C at t = {T;8} (when q = Q\u2080/\u221A2) \xB7 if the capacitor has Q\u2080 and the switch is closed at t = 0, then q = Q\u2080 cos \u03C9t \xB7 when the energy of L is three times that of C, q = Q\u2080/2 \xB7 the magnetic energy is largest when q = 0","Write q = Q\u2080cos \u03C9t and set the fraction of energy; do not use the period as a rule of thumb for energy ratios other than 1 : 1.","Q\u2080 = 100 \u03BCC, C = 10 \u03BCF: UE at q = 50 \u03BCC is (50 \xD7 10\u207B\u2076)\xB2 \xF7 2 \xD7 10\u207B\u2075 = 1.25 \xD7 10\u207B\u2074 J, a quarter of the total, so UB = 3.75 \xD7 10\u207B\u2074 J."),e("Power, LC oscillations and the transformer",1,"Ideal transformer","{Vs;Vp} = {Ns;Np} = {Ip;Is} \xB7 step-up: Ns > Np, Vs > Vp, Is < Ip \xB7 step-down: Ns < Np \xB7 ideal: Vs Is = Vp Ip (no loss of power) \xB7 works only on AC, because it needs a changing flux \xB7 the frequency is unchanged \xB7 it transfers energy through mutual induction","Take the turns ratio first, get Vs, then use the power equality to find the current.","Np = 1000, Ns = 100, Vp = 220 V: Vs = 22 V. If the secondary delivers 100 W, then Is = 100/22 = 4.5 A."),e("Power, LC oscillations and the transformer",1,"Efficiency and losses","\u03B7 = {output power;input power} = {VsIs;VpIp} \xB7 losses: copper loss I\xB2R in the windings, iron loss (eddy currents and hysteresis) in the core, flux leakage and humming \xB7 remedy: laminated core of soft iron, thick wire for the large current, windings on top of each other \xB7 efficiency is usually 95 % to 99 %","Input = output \xF7 \u03B7. Then Ip = input power \xF7 Vp.","Output 100 W at \u03B7 = 90 %: input = 111 W and Ip = 111 \xF7 220 = 0.505 A."),e("Power, LC oscillations and the transformer",1,"Transmission of power","line current I = {P;V} (at unit power factor) \xB7 loss = I\xB2R = {P\xB2R;V\xB2} \xB7 a higher voltage cuts the loss with the square \xB7 step up at the power station and step down near the user \xB7 fractional loss = {PR;V\xB2}","Write the loss as P\xB2R/V\xB2 and compare two voltages: ten times the voltage gives one hundredth of the loss.","P = 100 kW, line R = 2 \u03A9: at 2 kV, I = 50 A and loss = 5 kW (5 %). At 20 kV, I = 5 A and loss = 50 W (0.05 %)."),e("Power, LC oscillations and the transformer",2,"Lamp, heater and choke on AC","bulb of rating (P, V): R = {V\xB2;P}, e.g. 100 W, 220 V: R = 484 \u03A9 \xB7 a choke (inductor) in series dims the lamp without much loss of power, but a resistor wastes power as heat \xB7 DC through an inductor: only R matters \xB7 for the same rms, the lamp is equally bright on DC and AC","Find the resistance of the lamp from its rating and then treat it as R in the LCR formulas.","A 100 W, 220 V lamp is in series with an ideal coil on a 220 V supply. For half the power (50 W) the current falls by \u221A2, so Z = 484 \xD7 1.414 = 684 \u03A9 and XL = 484 \u03A9.")],look:["\u03A6 = BA cos\u03B8; \u03B5 = \u2212N d\u03A6/dt; q = N\u0394\u03A6/R (independent of time); Lenz: opposes the change of flux","Motional: \u03B5 = Blv; I = Blv/R; F = B\xB2l\xB2v/R; P = B\xB2l\xB2v\xB2/R; rotating rod \u03B5 = \xBDB\u03C9l\xB2; coil \u03B5 = NBA\u03C9 sin \u03C9t","\u03B5 = \u2212L dI/dt; L = \u03BC\u2080N\xB2A/l; M = \u03BC\u2080N\u2081N\u2082A/l; series L\u2081 + L\u2082 \xB1 2M; U = \xBDLI\xB2; u = B\xB2/2\u03BC\u2080","RL: \u03C4 = L/R; growth (E/R)(1 \u2212 e^(\u2212t/\u03C4)); decay I\u2080e^(\u2212t/\u03C4); at t = 0 open, at t = \u221E a wire","Eddy currents oppose the motion, heat the metal; laminate to cut them; motor back EMF Eb","rms = peak/\u221A2; half-cycle mean = 2\xB7peak/\u03C0; full-cycle mean 0; rms of DC + sine = \u221A(Id\xB2 + I\u2080\xB2/2)","XL = \u03C9L (V leads I); XC = 1/\u03C9C (I leads V); R in phase; Z = \u221A(R\xB2 + (XL \u2212 XC)\xB2); tan\u03C6 = (XL \u2212 XC)/R","Resonance: \u03C9\u2080 = 1/\u221ALC, Z = R, cos\u03C6 = 1; Q = \u03C9\u2080L/R = f\u2080/\u0394f; half-power at 0.707 of the peak","P = VI cos\u03C6 = I\xB2R; cos\u03C6 = R/Z; wattless I sin\u03C6; LC: T = 2\u03C0\u221ALC, UE = UB at q = Q\u2080/\u221A2; transformer Vs/Vp = Ns/Np = Ip/Is"],notes:[{h:"Magnetic flux and Faraday\u2019s law",items:["\u03A6 = BA cos\u03B8 with \u03B8 the angle between B and the normal to the loop.","A flux that changes in time induces an EMF; the size depends on the rate d\u03A6/dt.","The flux can change by B, by the area, or by the angle.","For N turns multiply by N: \u03B5 = \u2212N d\u03A6/dt.","A changing B also sets up a circular induced electric field around it.","A loop completely inside a uniform field, moving or not, has no EMF."],fig:"eifar"},{h:"Lenz\u2019s law and induced charge",items:["The induced current opposes the change of flux, not the flux itself.","Flux growing: the induced field is opposite to B. Flux falling: it is in the same sense.","A magnet approaching a coil is repelled; a leaving magnet is attracted.","Lenz\u2019s law is conservation of energy: the opposition has to be paid for by the work you do.","The charge q = N\u0394\u03A6/R does not depend on how fast the flux changes.","For a flip through 180\xB0 the change of flux is 2BA."]},{h:"Motional EMF",items:["A rod moving at right angles to B and to its length has \u03B5 = Blv.","On rails the current is Blv/R and the magnetic force B\xB2l\xB2v/R opposes the velocity.","The power you supply equals the heat in R, P = B\xB2l\xB2v\xB2/R.","At the terminal speed the force of the field balances the driving force.","A rod rotating about one end has \u03B5 = \xBDB\u03C9l\xB2, a disc is the same with l the radius.","A loop entering a field has a constant EMF during the entry, none when fully inside."],fig:"eirail"},{h:"Self and mutual inductance",items:["\u03B5 = \u2212L dI/dt: the inductor resists a change in current.","L = \u03BC\u2080N\xB2A/l for a solenoid, and it grows with N\xB2 and with an iron core.","M is the same for the two coils, and M \u2264 \u221A(L\u2081L\u2082).","Coils in series have L\u2081 + L\u2082 \xB1 2M depending on the sense of winding.","The unit of both is the henry, 1 H = 1 V s/A.","Energy density of a magnetic field is B\xB2/2\u03BC\u2080."]},{h:"RL circuits",items:["The current in an inductor cannot change suddenly.","At t = 0 an inductor in a branch behaves as an open circuit, at t = \u221E as a wire.","The time constant is \u03C4 = L/R, after which I reaches 63 % or falls to 37 %.","Growth is (E/R)(1 \u2212 e^(\u2212t/\u03C4)) and decay is I\u2080e^(\u2212t/\u03C4).","The energy \xBDLI\u2080\xB2 in an inductor is turned into heat in the resistor during decay.","Breaking the circuit quickly gives a large EMF and a spark."],fig:"eirl"},{h:"Eddy currents and generators",items:["Eddy currents are closed currents in a bulk conductor driven by a changing flux.","They oppose the motion by Lenz\u2019s law and they heat the metal.","Uses: induction furnace, electromagnetic braking, damping of galvanometer coils.","Laminated cores cut eddy-current loss in transformers and motors.","The generator gives \u03B5 = NBA\u03C9 sin \u03C9t from rotation.","A motor produces a back EMF which reduces the current as the speed grows."]},{h:"AC values and phasors",items:["The rms value is the peak divided by \u221A2; mains of 220 V rms has a peak of 311 V.","The mean over a half cycle is 2/\u03C0 times the peak; over a whole cycle it is zero.","Meters read rms, and heating depends on rms.","In a resistor V and I are in phase; in an inductor V leads I by 90\xB0; in a capacitor I leads V by 90\xB0.","XL = \u03C9L grows with f; XC = 1/\u03C9C falls with f.","The average power in a pure inductor or capacitor is zero."],fig:"eiphas"},{h:"Series LCR circuit and resonance",items:["Z = \u221A(R\xB2 + (XL \u2212 XC)\xB2) and tan\u03C6 = (XL \u2212 XC)/R.","At resonance XL = XC, Z = R, I is maximum and \u03C6 = 0.","f\u2080 = 1/(2\u03C0\u221A(LC)) depends on L and C only, not on R.","Q = \u03C9\u2080L/R = f\u2080/bandwidth: low R means a high Q and a sharp peak.","The voltages across L and C can each be Q times the supply at resonance.","The half-power points are where the current falls to 0.707 of the peak."],fig:"eirlc"},{h:"Power, LC oscillations and the transformer",items:["P = Vrms Irms cos\u03C6 and cos\u03C6 = R/Z.","The wattless current is Irms sin\u03C6 and carries no average power.","In an LC circuit energy swings between E and B fields, \u03C9 = 1/\u221A(LC).","An ideal transformer has Vs/Vp = Ns/Np = Ip/Is and works on AC only.","Losses in a real transformer: copper, eddy, hysteresis and flux leakage.","High-voltage transmission cuts the line loss, since loss = P\xB2R/V\xB2."]}],asked:[{t:"Flux through a tilted loop",what:"A loop of given area is in a uniform field at some angle. Find the flux, or the change of flux when the loop is turned.",steps:["Find \u03B8 between B and the normal.","\u03A6 = BA cos\u03B8.","Subtract final from initial flux for the change."],ex:"0.5 T, 0.02 m\xB2, 60\xB0 to the normal: 5 \xD7 10\u207B\xB3 Wb.",tp:"flux",fig:"eifar"},{t:"EMF from a changing B or a changing area",what:"B changes with time, or a coil is pulled out of a field. Find the average or the instantaneous EMF.",steps:["Write \u03A6 = NBA cos\u03B8.","\u03B5 = \u2212d\u03A6/dt (or \u0394\u03A6/\u0394t).","Put the given numbers; keep units in SI."],ex:"100 turns, flux falls by 0.015 Wb in 0.1 s: 15 V.",tp:"flux"},{t:"Direction of the induced current (Lenz\u2019s law)",what:"A magnet moves near a coil, or the field in a loop grows or falls. Find the direction of the current or the face that becomes a pole.",steps:["Is the flux growing or falling?","The induced field opposes the change.","Right-hand rule gives the current."],ex:"B into the page growing: anticlockwise current.",tp:"flux",fig:"eifar"},{t:"Charge that flows when the flux changes",what:"A coil is flipped, removed from a field or the field switched off. Find the charge that passes through the circuit.",steps:["q = N\u0394\u03A6/R.","Find the change of flux (2BA for a flip).","The time does not matter."],ex:"50 turns, flip in 0.2 T, 0.01 m\xB2, 5 \u03A9: 0.04 C.",tp:"flux"},{t:"EMF in a moving rod",what:"A rod moves in a field at some speed and orientation. Find the EMF, which end is positive, or the potential at a point.",steps:["Find the parts of v, l and B that are at right angles.","\u03B5 = Blv.","The direction comes from v \xD7 B."],ex:"0.5 m, 10 m/s, 0.2 T: 1 V.",tp:"motional",fig:"eirail"},{t:"Rod on rails: current, force and power",what:"A rod is pulled on rails joined by a resistor. Find the current, the force needed at constant speed and the power.",steps:["\u03B5 = Blv, I = \u03B5/R.","F = BIl = B\xB2l\xB2v/R.","P = Fv = I\xB2R."],ex:"1 V and 2 \u03A9: 0.5 A, 0.05 N, 0.5 W.",tp:"motional",fig:"eirail"},{t:"Terminal speed of a rod or a loop",what:"A rod slides under gravity or under a constant force on rails. Find the final constant speed.",steps:["At the terminal speed the force of the field equals the driving force.","B\xB2l\xB2v/R = F.","vT = FR/(B\xB2l\xB2)."],ex:"0.1 kg, 1 m, 1 \u03A9, 1 T, falling: 1 m/s.",tp:"motional"},{t:"Rotating rod or disc",what:"A rod or a metal disc rotates in a perpendicular field. Find the EMF between the axle and the rim.",steps:["Mean speed is \u03C9l/2.","\u03B5 = \xBDB\u03C9l\xB2.","Between r\u2081 and r\u2082 subtract the squares."],ex:"0.1 T, 0.5 m, 20 rad/s: 0.25 V.",tp:"motional"},{t:"Loop entering or leaving a field",what:"A rectangular loop moves into a region of field. Find the EMF, the current and the force in each stage, or choose the right graph.",steps:["EMF only while the flux changes.","\u03B5 = Bav while entering or leaving.","Zero when fully inside."],ex:"0.1 m loop, 0.5 T, 2 m/s: 0.1 V for 0.05 s.",tp:"motional"},{t:"Self-inductance of a solenoid",what:"The number of turns, area and length are given. Find L, or see how L changes when N, l or the core change.",steps:["L = \u03BC\u2080N\xB2A/l.","L \u221D N\xB2 and L \u221D 1/l.","An iron core multiplies L by \u03BCr."],ex:"1000 turns, 0.5 m, 2 \xD7 10\u207B\u2074 m\xB2: 0.5 mH.",tp:"induct"},{t:"Mutual inductance and coupled coils",what:"Two coils are coupled. Find M, the EMF in the secondary, or the inductance of two coils in series.",steps:["\u03B5\u2082 = \u2212M dI\u2081/dt.","M = k\u221A(L\u2081L\u2082).","L = L\u2081 + L\u2082 \xB1 2M."],ex:"2 H and 3 H with M = 1 H: 7 H or 3 H.",tp:"induct"},{t:"Energy stored in an inductor",what:"L and I are given, or the field in a solenoid. Find the energy or the energy per unit volume.",steps:["U = \xBDLI\xB2.","u = B\xB2/2\u03BC\u2080.","Compare U with a capacitor\u2019s \xBDCV\xB2."],ex:"0.5 H, 2 A: 1 J.",tp:"induct"},{t:"RL circuit: current at a given time",what:"A battery is connected to an RL circuit, or the battery is removed. Find the current at some time, the time constant or the time for a fraction.",steps:["\u03C4 = L/R.","Growth (E/R)(1 \u2212 e^(\u2212t/\u03C4)), decay I\u2080e^(\u2212t/\u03C4).","Half value at 0.693\u03C4."],ex:"12 V, 4 \u03A9, 2 H, t = 0.5 s: 1.90 A.",tp:"apps",fig:"eirl"},{t:"Switch just closed, or long after (inductor in a circuit)",what:"A circuit has resistors and an inductor. Find the current in some branch at t = 0 or at t = \u221E.",steps:["At t = 0 treat L as open.","At t = \u221E treat L as a wire.","Solve as a resistor circuit."],ex:"10 V, 5 \u03A9 and (5 \u03A9 \u2016 L): 1 A at t = 0, 2 A at t = \u221E.",tp:"apps"},{t:"Peak, rms and mean values",what:"A current or voltage function is given. Find the rms, the mean over a half cycle, or the heat produced.",steps:["rms = peak/\u221A2.","Half-cycle mean = 2\xB7peak/\u03C0.","For other waves, average the square."],ex:"3 + 4 sin \u03C9t: rms = 4.12 A.",tp:"rms"},{t:"Reactance, phase and the current in L-only or C-only circuits",what:"An AC source is connected to a pure inductor or a pure capacitor. Find the reactance, the current and the phase.",steps:["XL = \u03C9L, XC = 1/\u03C9C.","I = V/X.","L: V leads. C: I leads."],ex:"0.1 H, 50 Hz: 31.4 \u03A9, 7.0 A at 220 V.",tp:"react",fig:"eiphas"},{t:"Impedance and phase angle of LR, CR and LCR circuits",what:"R, L, C and f are given. Find Z, I, the phase angle and the voltage across each part.",steps:["Find XL and XC.","Z = \u221A(R\xB2 + (XL \u2212 XC)\xB2).","tan\u03C6 = (XL \u2212 XC)/R."],ex:"30 \u03A9, 70 \u03A9, 30 \u03A9: Z = 50 \u03A9, \u03C6 = 53\xB0.",tp:"rlc",fig:"eiphas"},{t:"Resonance, Q factor and bandwidth",what:"An LCR circuit is tuned to resonance. Find f\u2080, the current at resonance, Q, the bandwidth or the voltage across L.",steps:["f\u2080 = 1/(2\u03C0\u221ALC).","Q = \u03C9\u2080L/R, \u0394f = f\u2080/Q.","VL = QE at resonance."],ex:"1 mH, 10 \u03BCF, 2 \u03A9: f\u2080 = 1592 Hz, Q = 5, \u0394f = 318 Hz.",tp:"rlc",fig:"eirlc"},{t:"Power, power factor and wattless current",what:"The voltage and the circuit are given. Find the average power, cos\u03C6 or the wattless current.",steps:["cos\u03C6 = R/Z.","P = VrmsIrms cos\u03C6 = I\xB2R.","Wattless current = I sin\u03C6."],ex:"30 \u03A9, 40 \u03A9, 100 V: cos\u03C6 = 0.6, P = 120 W.",tp:"power"},{t:"LC oscillations: frequency and energy",what:"A charged capacitor is connected to an inductor. Find the frequency, the maximum current or the energy or charge at some moment.",steps:["\u03C9 = 1/\u221A(LC).","I\u2080 = Q\u2080\u03C9.","Total energy Q\u2080\xB2/2C is constant."],ex:"1 mH, 10 \u03BCF, 100 \u03BCC: \u03C9 = 10\u2074 rad/s, I\u2080 = 1 A, 5 \xD7 10\u207B\u2074 J.",tp:"power"},{t:"Transformer: voltage, current and efficiency",what:"The turns ratio, the input voltage and the load are given. Find the secondary voltage, the currents and the efficiency.",steps:["Vs/Vp = Ns/Np = Ip/Is.","Input = output \xF7 \u03B7.","Ip = input power \xF7 Vp."],ex:"1000 : 100 turns, 220 V: 22 V. 100 W at 90 %: 0.505 A.",tp:"power"},{t:"Power transmission and line losses",what:"Power is sent through a line of resistance R at some voltage. Find the line current, the loss or the effect of the voltage.",steps:["I = P/V.","Loss = I\xB2R = P\xB2R/V\xB2.","Loss falls as 1/V\xB2."],ex:"100 kW, 2 \u03A9: 5 kW at 2 kV, 50 W at 20 kV.",tp:"power"}],guide:{intro:"Electromagnetic Induction and Alternating Current is one of the highest-scoring chapters in JEE Mains, usually giving 2 or 3 questions together. They are formula-based: the flux and the EMF, the force and power in a moving rod, an RL circuit at a given time, the rms and mean values, the impedance of an LCR circuit, resonance and Q, power factor and a transformer. Learn the formulas and practise the circuits; about 8 hours spread over 5 days is enough.",plan:[["Day 1 \xB7 90 min","Flux, Faraday\u2019s law, Lenz\u2019s law, induced charge, motional EMF of a rod and of rotating rod or coil."],["Day 2 \xB7 90 min","Rod on rails with force and power, loop entering a field, self and mutual inductance, energy of an inductor."],["Day 3 \xB7 90 min","RL growth and decay, circuits at t = 0 and t = \u221E, eddy currents, generator and motor; then AC values rms and mean."],["Day 4 \xB7 90 min","Phasors, XL, XC, impedance of LR, CR and LCR, resonance, Q factor and bandwidth."],["Day 5 \xB7 75 min","Power factor, wattless current, LC oscillations, the transformer and transmission; then the Most asked types and a mock test."]],basics:["Magnetic field of a solenoid, B = \u03BC\u2080nI, and the force on a moving charge.","Capacitor basics: C, the energy \xBDCV\xB2 and the charging time constant RC.","Ohm\u2019s law and series and parallel resistors.","Sine functions, the period and the angular frequency \u03C9 = 2\u03C0f.","Vector cross product and the right-hand rule.","Simple harmonic motion and the energy of a spring and mass."],path:[{t:"Step 1 \xB7 Faraday and Lenz (Day 1)",d:"Learn \u03A6 = BA cos\u03B8, \u03B5 = \u2212N d\u03A6/dt, the direction rule and the charge q = N\u0394\u03A6/R.",ready:"you can give the direction of the current and the charge for a coil flipped in a field.",go:"formulas"},{t:"Step 2 \xB7 Motional EMF (Day 1\u20132)",d:"Learn \u03B5 = Blv, the force B\xB2l\xB2v/R, the terminal speed and \xBDB\u03C9l\xB2 for the rotating rod.",ready:"you can find the current, the force and the power for a rod on rails without a hint.",go:"formulas"},{t:"Step 3 \xB7 Inductance and RL circuits (Day 2\u20133)",d:"Learn L, M, the energy \xBDLI\xB2 and the RL curves, with t = 0 and t = \u221E rules.",ready:"you can find the current in any branch just after closing and long after.",go:"notes"},{t:"Step 4 \xB7 AC and phasors (Day 3\u20134)",d:"Learn the rms and mean values, XL, XC, the phase rules and Z for a series circuit.",ready:"you can find Z, I and \u03C6 for a given LCR circuit in under a minute.",go:"formulas"},{t:"Step 5 \xB7 Resonance, power and the transformer (Day 4\u20135)",d:"Learn resonance, Q, power factor, LC oscillations and the ideal transformer.",ready:"you can find f\u2080, Q and the bandwidth, and solve a transformer problem with efficiency.",go:"asked"},{t:"Step 6 \xB7 Practise, then test",d:"Practise by question type, then take the mock test.",ready:"you score 8 out of 10 in practice twice in a row.",go:"practice"}],think:["Is it induction (a changing flux) or AC (a source of constant \u03C9)?","For an EMF, which of B, A or \u03B8 changes, or does a conductor cut the field lines?","Flux growing or falling? This decides the direction of the induced current.","For an RL problem, is it t = 0, t = \u221E or a given t? Do you need \u03C4?","For AC: peak or rms? Meters and power use rms.","Find XL and XC first, then Z, then \u03C6, and only then the power.","Check that every quantity is in SI units (H, F, \u03A9, Hz or rad/s) before putting it in a formula."],watch:["Mixing up f and \u03C9: XL = 2\u03C0fL and XC = 1/(2\u03C0fC).","The angle in \u03A6 = BA cos\u03B8 is with the normal, not with the plane.","Using the peak where the rms is needed in P = VI cos\u03C6.","Taking the current in an inductor as jumping at t = 0; it cannot change suddenly.","Adding R, XL and XC directly: Z is the vector sum, with XL and XC in opposite directions.","Saying that L, C or R at resonance have zero voltage; VL = VC = QE, only the sum is zero.","Taking the average of an AC over a full cycle as 0.637 of the peak (that is for a half cycle).","The transformer needs AC; with DC the secondary shows no steady voltage."],myths:[["Myth: The induced EMF depends on the flux through the loop.","Truth: It depends on the rate of change of flux. A large constant flux gives no EMF."],["Myth: Lenz\u2019s law says the induced field is opposite to the applied field.","Truth: It opposes the change of flux. When the flux falls, the induced field is in the same direction as B."],["Myth: A heavy magnet falls freely through a copper tube.","Truth: Eddy currents in the tube oppose the fall, so the magnet reaches a small terminal speed."],["Myth: The inductor stops the current.","Truth: It resists a change of current. A steady current passes freely."],["Myth: The current in an RL circuit reaches E/R in a time \u03C4.","Truth: After \u03C4 it has reached only 63 % of its final value. It takes several \u03C4 to settle."],["Myth: AC of 220 V has a maximum of 220 V.","Truth: 220 V is the rms value. The peak is 311 V."],["Myth: A capacitor in AC is an open circuit.","Truth: It passes AC with a reactance 1/\u03C9C. It blocks only DC."],["Myth: At resonance the voltage across L and C is zero.","Truth: Each is Q times the supply, and they are 180\xB0 apart so they cancel in the sum."],["Myth: A pure inductor consumes power.","Truth: The average power is zero. It stores and returns the energy each quarter cycle."],["Myth: A transformer can increase both the voltage and the power.","Truth: A step-up transformer raises V and lowers I; the output power is never more than the input."]]},extra:[]}})()})();
